"""Read-only summary of a node's llmcall usage and budget differences."""
import argparse
from datetime import datetime, timezone
import json
from pathlib import Path
import sys


def load_object(path):
    def reject_constant(value):
        raise ValueError("invalid JSON constant: " + value)

    value = json.loads(path.read_text(encoding="utf-8"), parse_constant=reject_constant)
    if not isinstance(value, dict):
        raise ValueError("expected JSON object")
    return value


def amount(value):
    if value is None:
        return 0
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError("expected integer or null")
    return value


def period_of(raw, by):
    at = raw["at"]
    if isinstance(at, bool) or not isinstance(at, (int, float)):
        raise ValueError("invalid timestamp")
    stamp = datetime.fromtimestamp(at, timezone.utc)
    return stamp.strftime("%Y-%m-%d" if by == "day" else "%Y-%m-%dT%H")


def ledger_used(node, budget):
    try:
        value = load_object(node / "budget" / budget / "ledger.json")["used"]
        return value if isinstance(value, int) and not isinstance(value, bool) else None
    except (OSError, UnicodeError, ValueError, KeyError):
        return None


def summarize(node, by):
    totals = {}
    receipts = {}
    gaps = []
    budgets = set()
    budget_root = node / "budget"
    if budget_root.is_dir():
        budgets.update(path.name for path in budget_root.iterdir() if path.is_dir())

    call_root = node / "llmcall"
    if call_root.is_dir():
        for budget_dir in sorted(path for path in call_root.iterdir() if path.is_dir()):
            budget = budget_dir.name
            for call_dir in sorted(path for path in budget_dir.iterdir() if path.is_dir()):
                request_path = call_dir / "request.json"
                if not request_path.is_file():
                    continue
                budgets.add(budget)
                reasons = set()
                model = holder = None
                try:
                    request = load_object(request_path)
                    holder = request["holder"]
                    model = request.get("request", {}).get("model")
                    if not isinstance(model, str):
                        model = request["endpoint"]
                    if not isinstance(holder, str) or not isinstance(model, str):
                        raise ValueError("invalid request fields")
                except (OSError, UnicodeError, ValueError, KeyError, TypeError, AttributeError):
                    reasons.add("bad_json")

                used = overrun = None
                receipt_path = call_dir / "receipt.json"
                if not receipt_path.exists():
                    reasons.add("no_receipt")
                else:
                    try:
                        receipt = load_object(receipt_path)
                        used = amount(receipt["used"])
                        overrun = amount(receipt["overrun"])
                        if overrun > 0:
                            reasons.add("overrun")
                    except (OSError, UnicodeError, ValueError, KeyError):
                        reasons.add("bad_json")

                period = "-"
                raw_path = call_dir / "raw.json"
                if raw_path.exists():
                    try:
                        period = period_of(load_object(raw_path), by)
                    except (OSError, UnicodeError, ValueError, KeyError, OverflowError):
                        reasons.add("bad_json")

                # A malformed request or raw invalidates the call, including its receipt total.
                if "bad_json" not in reasons and "no_receipt" not in reasons:
                    receipts[budget] = receipts.get(budget, 0) + used
                    row = totals.setdefault((model, holder, period), [0, 0, 0])
                    row[0] += 1
                    row[1] += used
                    row[2] += overrun
                gaps.extend({"budget": budget, "call_id": call_dir.name, "why": why} for why in reasons)

    groups = [dict(model=model, holder=holder, period=period, calls=values[0], used=values[1], overrun=values[2]) for (model, holder, period), values in sorted(totals.items())]
    budget_rows = []
    for budget in sorted(budgets):
        ledger = ledger_used(node, budget)
        total = receipts.get(budget, 0)
        budget_rows.append(dict(budget=budget, receipts_used=total, ledger_used=ledger, diff=None if ledger is None else ledger - total))
    gaps.sort(key=lambda row: (row["budget"], row["call_id"], row["why"]))
    return dict(v=1, by=by, groups=groups, budgets=budget_rows, gaps=gaps)


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only llmcall usage summary")
    parser.add_argument("node")
    parser.add_argument("--by", choices=("day", "hour"), default="day")
    args = parser.parse_args(argv)
    node = Path(args.node)
    if not node.is_dir():
        print("aos7-usage: node is not a directory", file=sys.stderr)
        return 2
    print(json.dumps(summarize(node, args.by), ensure_ascii=True, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
